Manacher 算法可以计算以 $s[i]$（或者 $s[i]$ 和 $s[i+1]$）为回文中心的最长回文子串的长度。

此外，还可以：

- 判断任意子串是否为回文串。
- 计算从 $s[i]$ 开始的最长回文子串的长度。
- 计算以 $s[i]$ 结尾的最长回文子串的长度。

> **注**：Z 函数和 Manacher 算法都会用到类似 Z-box 的概念，在学习时，可以对比体会。

Manacher 算法模板：

```py [sol-Python3]
class Manacher:
    def __init__(self, s: str):
        # 将 s 改造为 t，这样就不需要讨论 len(s) 的奇偶性，因为新串 t 的每个回文子串都是奇回文串（都有回文中心）
        # s 和 t 的下标转换关系：
        # (si+1)*2 = ti
        # ti/2-1 = si
        # ti 为偶数，对应奇回文串（从 2 开始）
        # ti 为奇数，对应偶回文串（从 3 开始）
        t = "#".join("^" + s + "$")

        # 定义一个奇回文串的回文半径=(长度+1)/2，即保留回文中心，去掉一侧后的剩余字符串的长度
        # half_len[i] 表示在 t 上的以 t[i] 为回文中心的最长回文子串的回文半径
        # 即 [i-half_len[i]+1, i+half_len[i]-1] 是 t 上的一个回文子串
        half_len = [0] * (len(t) - 2)
        half_len[1] = 1

        # box_r 表示当前右边界下标最大的回文子串的右边界下标+1
        # box_m 为该回文子串的中心位置
        # 二者的关系为 box_r = box_m + half_len[box_m]
        box_m = box_r = 0
        for i in range(2, len(half_len)):
            hl = 1
            if i < box_r:
                # 记 i 关于 box_m 的对称位置 i'=box_m*2-i
                # 若以 i' 为中心的最长回文子串范围超出了以 box_m 为中心的回文串的范围
                # 则 half_len[i] 应先初始化为已知的回文半径 box_r-i，然后再继续暴力匹配
                # 否则 half_len[i] 与 half_len[i'] 相等
                hl = min(box_r - i, half_len[box_m * 2 - i])

            # 暴力扩展
            # 算法的复杂度取决于这部分执行的次数
            # 由于扩展之后 box_r 必然会更新（右移），且扩展的的次数就是 box_r 右移的次数
            # 因此算法的复杂度 = O(len(t)) = O(n)
            while t[i - hl] == t[i + hl]:
                hl += 1
                box_m, box_r = i, i + hl

            half_len[i] = hl

        self.half_len = half_len

    # 判断子串 s[l:r]（左闭右开）是否为回文串
    def is_palindrome(self, l: int, r: int) -> bool:
        # 根据下标转换关系得到子串 s[l:r] 在 t 中对应的回文中心下标为 l+r+1
        # t 中回文子串的长度为 hl*2-1
        # 由于其中 '#' 的数量总是比字母的数量多 1
        # 因此其在 s 中对应的回文子串的长度为 hl-1
        return self.half_len[l + r + 1] > r - l  # half_len[l+r+1]-1 >= r-l

    # is_odd=True:  返回以 s[i] 为回文中心的最长奇回文子串长度
    # is_odd=False: 返回以 s[i] 和 s[i+1] 为回文中心的最长偶回文子串长度（若不存在，则为 0）
    def longest_palindrome_at(self, i: int, is_odd: bool) -> int:
        # 根据下标转换关系得到在 t 中对应的回文中心下标
        if is_odd:
            return self.half_len[i * 2 + 2] - 1
        return self.half_len[i * 2 + 3] - 1
```

```java [sol-Java]
class Manacher {
    private final int[] halfLen;

    public Manacher(String s) {
        // 将 s 改造为 t，这样就不需要讨论 s.length() 的奇偶性，因为新串 t 的每个回文子串都是奇回文串（都有回文中心）
        // s 和 t 的下标转换关系：
        // (si+1)*2 = ti
        // ti/2-1 = si
        // ti 为偶数，对应奇回文串（从 2 开始）
        // ti 为奇数，对应偶回文串（从 3 开始）
        int n = s.length();
        char[] t = new char[n * 2 + 3];
        Arrays.fill(t, '#');
        t[0] = '^';
        for (int i = 0; i < n; i++) {
            t[i * 2 + 2] = s.charAt(i);
        }
        t[n * 2 + 2] = '$';

        // 定义一个奇回文串的回文半径=(长度+1)/2，即保留回文中心，去掉一侧后的剩余字符串的长度
        // halfLen[i] 表示在 t 上的以 t[i] 为回文中心的最长回文子串的回文半径
        // 即 [i-halfLen[i]+1, i+halfLen[i]-1] 是 t 上的一个回文子串
        halfLen = new int[t.length - 2];
        halfLen[1] = 1;

        // boxR 表示当前右边界下标最大的回文子串的右边界下标+1
        // boxM 为该回文子串的中心位置
        // 二者的关系为 boxR = boxM + halfLen[boxM]
        int boxM = 0;
        int boxR = 0;
        for (int i = 2; i < halfLen.length; i++) {
            int hl = 1;
            if (i < boxR) {
                // 记 i 关于 boxM 的对称位置 i'=boxM*2-i
                // 若以 i' 为中心的最长回文子串范围超出了以 boxM 为中心的回文串的范围
                // 则 halfLen[i] 应先初始化为已知的回文半径 boxR-i，然后再继续暴力匹配
                // 否则 halfLen[i] 与 halfLen[i'] 相等
                hl = Math.min(boxR - i, halfLen[boxM * 2 - i]);
            }

            // 暴力扩展
            // 算法的复杂度取决于这部分执行的次数
            // 由于扩展之后 boxR 必然会更新（右移），且扩展的的次数就是 boxR 右移的次数
            // 因此算法的复杂度 = O(t.length) = O(n)
            while (t[i - hl] == t[i + hl]) {
                hl++;
                boxM = i;
                boxR = i + hl;
            }

            halfLen[i] = hl;
        }
    }

	// 判断 s 的子串 [l,r] 是否为回文串
    public boolean isPalindrome(int l, int r) {
        // 根据下标转换关系得到子串 s[l,r] 在 t 中对应的回文中心下标为 l+r+2
        // t 中回文子串的长度为 hl*2-1
        // 由于其中 '#' 的数量总是比字母的数量多 1
        // 因此其在 s 中对应的回文子串的长度为 hl-1
		return halfLen[l + r + 2] > r - l + 1; // halfLen[l+r+2]-1 >= r-l+1
    }

    // isOdd=true:  返回以 s[i] 为回文中心的最长奇回文子串长度
    // isOdd=false: 返回以 s[i] 和 s[i+1] 为回文中心的最长偶回文子串长度（若不存在，则为 0）
    public int longestPalindromeAt(int i, boolean isOdd) {
        // 根据下标转换关系得到在 t 中对应的回文中心下标
        if (isOdd) {
            return halfLen[i * 2 + 2] - 1;
        }
        return halfLen[i * 2 + 3] - 1;
    }
}
```

