                // 若以 i' 为中心的最长回文子串范围超出了以 box_m 为中心的回文串的范围
                // 则 half_len[i] 应先初始化为已知的回文半径 box_r-i，然后再继续暴力匹配
                // 否则 half_len[i] 与 half_len[i'] 相等
                hl = min(box_r - i, half_len[box_m * 2 - i]);
