	// isOdd=false: 返回以 s[i] 和 s[i+1] 为回文中心的最长偶回文子串长度（若不存在，则为 0）
	midLen := func(i int, isOdd bool) int {
		// 根据下标转换关系得到在 t 中对应的回文中心下标
		if isOdd {
			return halfLen[i*2+2] - 1
		}
		return halfLen[i*2+3] - 1
	}


